package com.runloyal.booking.web; import com.runloyal.booking.context.TenantContext; import com.runloyal.booking.service.PlatformService; import jakarta.servlet.http.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.*; import java.util.*;
@RestControllerAdvice public class Errors { Dto.ApiError error(HttpStatus s,String c,String m,HttpServletRequest r){return new Dto.ApiError(Instant.now(),s.value(),c,m,r.getRequestURI(),Map.of());}@ExceptionHandler(NoSuchElementException.class) @ResponseStatus(HttpStatus.NOT_FOUND) Dto.ApiError notfound(NoSuchElementException e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"NOT_FOUND",e.getMessage(),r);}@ExceptionHandler({TenantContext.Forbidden.class,org.springframework.security.access.AccessDeniedException.class})@ResponseStatus(HttpStatus.FORBIDDEN)Dto.ApiError forbidden(Exception e,HttpServletRequest r){return error(HttpStatus.FORBIDDEN,"FORBIDDEN",e.getMessage(),r);}@ExceptionHandler(PlatformService.Conflict.class)@ResponseStatus(HttpStatus.CONFLICT)Dto.ApiError conflict(Exception e,HttpServletRequest r){return error(HttpStatus.CONFLICT,"CONFLICT",e.getMessage(),r);}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})@ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)Dto.ApiError invalid(Exception e,HttpServletRequest r){return error(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID",e.getMessage(),r);}@ExceptionHandler(MethodArgumentNotValidException.class)@ResponseStatus(HttpStatus.BAD_REQUEST)Dto.ApiError validation(MethodArgumentNotValidException e,HttpServletRequest r){var x=new LinkedHashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(f->x.put(f.getField(),f.getDefaultMessage()));return new Dto.ApiError(Instant.now(),400,"VALIDATION","Request validation failed",r.getRequestURI(),x);}}
